<div class="field"><label><?php echo $this->lang('Display') ?></label><select name="settings[mode]" class="ui fluid selection dropdown"><option value="upcoming"<?php if (($settings['mode'] ?? 'upcoming') === 'upcoming') echo ' selected'; ?>><?php echo $this->lang('Upcoming matches') ?></option><option value="results"<?php if (($settings['mode'] ?? '') === 'results') echo ' selected'; ?>><?php echo $this->lang('Results') ?></option><option value="all"<?php if (($settings['mode'] ?? '') === 'all') echo ' selected'; ?>><?php echo $this->lang('All') ?></option></select></div><div class="field"><label><?php echo $this->lang('Team') ?></label><select name="settings[team_id]" class="ui fluid selection dropdown"><option value="0"><?php echo $this->lang('All teams') ?></option><?php foreach ($teams as $team): ?><option value="<?php echo (int)$team['team_id'] ?>"<?php if ((int)($settings['team_id'] ?? 0) === (int)$team['team_id']) echo ' selected'; ?>><?php echo utf8_htmlentities($team['title']) ?></option><?php endforeach ?></select></div><div class="field"><label><?php echo $this->lang('Limit') ?></label><input type="number" min="1" max="24" name="settings[limit]" value="<?php echo (int)($settings['limit'] ?? 5) ?>" /></div>
